using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace ChartDesignerPro
{
    /// <summary>
    /// XrmToolBox entry point (discovered through MEF).
    /// Icons: Resources/icon32.png (SmallImageBase64) and Resources/icon80.png (BigImageBase64), rendered from Resources/icon.svg.
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Chart Designer Pro"),
     ExportMetadata("Description", "Inspect, validate and edit Dataverse charts: browse system and personal charts, read their data and presentation XML with Unified Interface compatibility checks, and save changes safely with a diff, a backup and scoped publishing."),
     ExportMetadata("SmallImageBase64", ""),
     ExportMetadata("BigImageBase64", ""),
     ExportMetadata("BackgroundColor", "#E0F2F1"),
     ExportMetadata("PrimaryFontColor", "#00695C"),
     ExportMetadata("SecondaryFontColor", "#5E6B69")]
    public class ChartDesignerProPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new ChartDesignerProControl();
        }
    }
}
